# 2급 CH13 가정법 (121~130) 2차 감수
X(2, 121, r="가정법 과거는 현재 사실과 반대되는 일을 가정한다: If + 주어 + 과거형, 주어 + would + 동사원형.",
  n=["조동사 would가 없어 가정법 주절이 되지 못하므로", "직설법 현재형이라 가정법 주절이 되지 못하므로", "will은 if절이 현재형일 때 쓰므로", "if절이 과거형 knew이므로 주절은 would + 동사원형이 알맞으므로", "현재완료는 가정법의 주절에 쓰지 않으므로"],
  st="① if절의 동사({0})가 과거형이다. 과거의 일이 아니라 현재 사실과 반대되는 가정이다(가정법 과거). → ② 가정법 과거의 주절은 ‘would + 동사원형’이다. will은 if절이 현재형일 때 쓴다. → ③ 정답은 {a}.",
  R="knew", B="had", C="knew", D="lived", E="spoke", F="had")

X(2, 122, r="as if + 가정법 과거완료(had + 과거분사)는 주절보다 앞선 일을 사실과 반대로 ‘마치 ~했던 것처럼’ 말할 때 쓴다.",
  n=["이전에 가 본 경험을 가정하는 것이라 과거형으로는 나타낼 수 없으므로", "직설법 현재형이라 가정의 뜻이 없으므로", "주어 he에 am을 쓸 수 없으므로", "가 본 적이 없다는 사실과 반대로, 주절보다 앞선 경험을 가정하므로 had been이 알맞으므로", "has been은 실제로 가 봤다는 뜻이 되어 직설법 문장과 어긋나므로"],
  st="① 직설법 문장에서 사실을 확인한다. {0} → ② as if 뒤는 그 사실과 반대로 가정한다. 말하는 때(주절)보다 앞선 일이므로 가정법 과거완료(had + 과거분사)를 쓴다. → ③ 정답은 {a}.",
  R="그는 파리에 가 본 적이 없다.", B="그는 콘서트에 가지 않았다.", C="그녀는 사고를 보지 못했다.", D="그는 그곳에 산 적이 없다.", E="그녀는 회의에 참석하지 않았다.", F="그는 그 책을 읽지 않았다.")

X(2, 123, r="실제로 일어날 수 있는 조건은 If + 현재형, will + 동사원형으로 쓰고, 현재 사실과 반대되는 가정은 If + 과거형, would + 동사원형으로 쓴다.",
  n=["둘째 문장은 가정법 과거라 would give가 필요하므로", "첫째 빈칸은 현재형이어야 하고 둘째 빈칸에도 would가 필요하므로", "둘째 문장의 if절이 과거형 won이므로 will을 쓸 수 없으므로", "두 빈칸 모두 맞지 않으므로", "조건문은 have - will call, 가정법 과거는 won - would give로 짝을 이루므로"],
  st="① 첫째 문장은 주절이 will이다. 실제로 일어날 수 있는 조건이므로 if절은 현재형({0})이다. → ② 둘째 문장은 if절이 과거형({1})이다. 가정법 과거이므로 주절은 would + 동사원형({2})이다. → ③ 정답은 {n}.",
  R=("have", "won", "would give"), B=("have", "found", "would take"), C=("is", "won", "would donate"), D=("comes", "knew", "would tell"), E=("is", "owned", "would give"), F=("buy", "lived", "would meet"))

X(2, 124, r="I wish, If only 뒤에는 가정법을 쓴다. 현재 사실의 반대는 과거형(were, could), 과거 사실의 반대는 had + 과거분사다. will, can은 쓸 수 없다.",
  n=["If + had + 과거분사로 과거 사실의 반대를 바르게 가정했으므로", "I wish + had + 과거분사로 지난 일의 아쉬움을 바르게 나타냈으므로", "If only + could로 올바르므로", "I wish 뒤에는 will을 쓸 수 없다. I were(would be)로 써야 하므로", "가정법 과거완료의 if절로 올바르므로"],
  st="① 밑줄마다 I wish, If only, If 뒤의 동사 형태를 본다. 현재 사실의 반대는 과거형(were, could), 과거 사실의 반대는 had + 과거분사다. → ② 이 자리에 현재형이나 will, can이 있으면 틀린 것이다. if절은 주절의 형태와도 짝이 맞아야 한다. → ③ {n}이 틀렸다: {0}.",
  R="I wish 뒤에 will be를 썼다. were(would be)가 맞다", B="I wish 뒤에 can play를 썼다. could play가 맞다", C="주절이 would lend인데 if절에 have를 썼다. had가 맞다", D="I wish 뒤에 will go를 썼다. could go가 맞다",
  E="주절이 would get인데 if절에 allows를 썼다. allowed가 맞다", F="주절이 would have bought인데 if절에 have known을 썼다. had known이 맞다")

X(2, 125, r="가정법 과거는 ‘과거형 - would + 동사원형’, 가정법 과거완료는 ‘had + 과거분사 - would have + 과거분사’로 짝을 이룬다. as if, I wish 뒤에도 같은 형태를 쓴다.",
  pre=["문장별 판정: ⓐ O. as if + were. ⓑ O. 가정법 과거. ⓒ X. yesterday의 일이고 주절이 would have helped이므로 if절은 had been. ⓓ O. I wish + could. ⓔ O. I wish + had + 과거분사. ⓕ O. as if + had + 과거분사."],
  k="틀린 문장은 ⓒ 하나다.", n=["틀린 문장은 ⓒ 하나뿐이므로"] * 5,
  st="① 문장마다 if절과 주절의 짝을 본다. 가정법 과거는 ‘과거형 - would + 동사원형’, 가정법 과거완료는 ‘had + 과거분사 - would have + 과거분사’다. → ② I wish, as if 뒤에는 과거형이나 had + 과거분사를 쓴다. 현재형, will, can은 틀린다. → ③ {0} 틀린 문장은 {a}이다.",
  R="ⓒ만 틀렸다. 과거(yesterday)의 일이고 주절이 would have helped이므로 if절은 had been이어야 한다.", B="ⓒ는 I wish I knew, ⓕ는 I would take로 써야 한다.",
  C="ⓒ는 I wish I had, ⓓ는 she would have caught, ⓕ는 If I were you로 써야 한다.", D="ⓑ는 I would wait, ⓒ는 I wish I had seen, ⓔ는 she were, ⓕ는 I would have helped로 써야 한다.",
  E="ⓑ는 If we had a car, ⓕ는 I wish it were Friday로 써야 한다.", F="ⓑ는 I would call, ⓒ는 I wish I were, ⓓ는 they would have arrived, ⓔ는 she could fly, ⓕ는 we would have made로 써야 한다. ⓐ만 옳다.")
RV(2, 125, "E", fx=True, why="수정 예시의 정답(1개, ①)이 원문항의 정답 개수·위치와 같아, ⓕ를 틀린 문장(I wish it is Friday today.)으로 바꿔 2개(②)로 했다.")

X(2, 126, r="가정법 과거완료는 과거 사실과 반대되는 일을 가정한다: If + 주어 + had + 과거분사, 주어 + would have + 과거분사.",
  n=["현재완료는 가정법의 if절에 쓰지 않으므로", "주절이 wouldn't have been이므로 과거형이 아니라 had + 과거분사가 필요하므로", "가정법 과거완료의 if절은 had + 과거분사이므로", "if절에는 would를 쓰지 않으므로", "would have + 과거분사는 주절의 형태이므로"],
  st="① 주절의 동사({0})가 ‘would have + 과거분사’다. 과거 사실과 반대되는 가정(가정법 과거완료)이다. → ② 가정법 과거완료의 if절은 ‘had + 과거분사’다. would는 주절에만 쓴다. → ③ 괄호 속 동사({1})를 had + 과거분사로 바꾼 {a}가 정답이다.",
  R=("wouldn't have been", "leave"), B=("wouldn't have gotten", "check"), C=("wouldn't have missed", "wake"), D=("would have seen", "buy"), E=("wouldn't have gotten", "bring"), F=("would have won", "practice"))

X(2, 127, r="as if(as though) + 가정법 과거는 ‘마치 ~인 것처럼’이라는 뜻으로, 주절과 같은 때의 사실과 반대되는 일을 나타낸다. be동사는 were를 쓴다.",
  n=["as if 뒤에 직설법 is를 써서 사실과 반대라는 뜻이 드러나지 않으므로", "as if + 주어 + were로 사실과 반대되는 가정을 나타내므로", "as만으로는 ‘마치 ~인 것처럼’을 나타낼 수 없으므로", "like 뒤에 가정법 were를 쓰는 것은 알맞지 않으므로", "as though 뒤에 직설법 is를 썼으므로"],
  st="① ‘마치 ~인 것처럼’은 as if(as though) + 가정법이다. {0} → ② 주절과 같은 때의 일을 사실과 반대로 가정하므로 가정법 과거를 쓴다. be동사는 주어와 관계없이 were다. → ③ as if(as though)와 were가 모두 갖춰진 {a}가 정답이다.",
  R="실제로 그는 회사의 사장이 아니다.", B="뒤의 although she is only an intern이 실제 사실을 알려 준다.", C="뒤의 but he is only a customer가 실제 사실을 알려 준다.", D="뒤의 but he isn't가 실제 사실을 알려 준다.",
  E="뒤의 but she isn't가 실제 사실을 알려 준다.", F="뒤의 but he isn't가 실제 사실을 알려 준다.")

X(2, 128, r="과거 사실과 반대되는 가정은 가정법 과거완료로 쓴다: If + had + 과거분사, would have + 과거분사.",
  n=["어젯밤의 일이므로 가정법 과거가 아니라 과거완료를 써야 하므로", "아파서 못 간 과거 사실의 반대이므로 had been - would have come이 알맞으므로", "직설법이라 가정의 뜻을 나타내지 못하므로", "현재형 am은 과거의 일을 가정하지 못하므로", "주절도 과거의 일이므로 would come이 아니라 would have come이어야 하므로"],
  st="① A의 질문({0})과 B의 대답으로 때를 확인한다. 이미 지난 과거의 일이다. → ② 과거 사실과 반대되는 가정은 가정법 과거완료다. if절은 had + 과거분사, 주절은 would have + 과거분사다. → ③ 두 자리가 모두 맞는 {n}을 고른다. 한쪽만 과거완료인 보기가 함정이다.",
  R="Why didn't you come ~ last night?", B="Why didn't you join ~?", C="Why did Tom miss ~?", D="Why didn't Mina buy ~?", E="Why didn't they win ~?", F="Why didn't Jane call ~?")

X(2, 129, r="가정법 과거완료(If + had + 과거분사, would have + 과거분사)는 과거 사실과 반대되는 가정이다. had는 주어에 따라 바뀌지 않는다. 직설법으로 바꾸면 과거 시제의 부정문이 된다.",
  n=["had + 과거분사가 과거 사실의 반대를 가정하므로 옳은 설명이므로", "would have + 과거분사가 과거의 가상 결과를 나타내므로 옳은 설명이므로", "실제로는 날씨가 좋지 않아 가지 못했다는 뜻이므로 옳은 설명이므로", "가정법의 had는 주어가 달라져도 has로 바뀌지 않으므로",
     "직설법은 As the weather was not good, we didn't go ~로 과거 부정문이 들어가 옳은 설명이므로"],
  st="① 문장은 ‘If + had + 과거분사, would have + 과거분사’, 곧 가정법 과거완료다. 과거 사실과 반대되는 가정이다. → ② 직설법으로 바꿔 실제 사실을 확인한다. {0} → ③ 이 내용과 어긋나는 설명은 {n}이다. {1}",
  R=("날씨가 좋지 않아서 해변에 가지 못했다.", "가정법의 had는 주어가 달라져도 has로 바뀌지 않는다."), B=("미나는 주소를 확인하지 않아서 건물을 찾지 못했다.", "would have found는 미래가 아니라 과거의 가상 결과다."),
  C=("톰은 일찍 떠나지 않아서 기차를 놓쳤다.", "직설법은 As Tom didn't leave earlier, he didn't catch the train.이다."), D=("우리는 사실을 몰라서 다르게 행동하지 못했다.", "had known은 현재가 아니라 과거 사실의 반대다."),
  E=("제인은 더 열심히 공부하지 않아서 떨어졌다.", "studied로 바꾸면 가정법 과거가 되어 시제와 뜻이 달라진다."), F=("그들은 택시를 타지 않아서 더 일찍 도착하지 못했다.", "실제로는 택시를 타지 않았다."))

X(2, 130, r="I wish + 가정법 과거완료(had + 과거분사)는 지난 일에 대한 아쉬움을 나타낸다. 과거 시점 표현이 있으면 과거형이 아니라 had + 과거분사를 쓴다.",
  pre=["문장별 판정: 첫째 O. last night의 일이므로 had seen. 둘째 X. when she was young의 일이므로 had been. 셋째 O. had told. 넷째 X. had have가 아니라 had had. 다섯째 O. had not lost."],
  k="옳은 문장은 첫째, 셋째, 다섯째 세 개다.", n=["옳은 문장은 첫째, 셋째, 다섯째 세 개이므로"] * 5,
  st="① I wish, as if, If 뒤의 동사 형태를 본다. 지금 일의 반대는 과거형(were, could), 지난 일의 반대는 had + 과거분사다. → ② 문장 속 시간 표현(now, yesterday, last year 등)과 견주고, 과거분사의 형태도 확인한다. → ③ {0} 옳은 문장은 {a}이다.",
  R="둘째는 과거(when she was young)의 일이므로 had been, 넷째는 had had로 써야 한다. 나머지 셋이 옳다.", B="다섯째만 틀렸다. I wish 뒤에는 can이 아니라 could를 쓴다.",
  C="다섯째만 틀렸다. go의 과거분사는 went가 아니라 gone이다.", D="다섯째만 틀렸다. wishes 뒤에는 is가 아니라 were를 쓴다.",
  E="첫째는 I knew, 넷째는 she would help, 다섯째는 we could로 써야 한다. 둘째와 셋째만 옳다.", F="첫째는 had listened, 둘째는 were, 넷째는 would have paid, 다섯째는 could로 써야 한다. 셋째만 옳다.")
